import{_ as l,a0 as r,w as a,s as d,I as n,x as t,a1 as s,A as o,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"Linux有問必答：Linux上如何安裝Shrew Soft IPsec VPN | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：Linux上如何安裝Shrew Soft IPsec VPN | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：Linux上如何安裝Shrew Soft IPsec VPN | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：Linux上如何安裝Shrew Soft IPsec VPN | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150506 Linux FAQs with Answers--How to install Shrew Soft IPsec VPN client on Linux","title":"Linux有問必答：Linux上如何安裝Shrew Soft IPsec VPN","tag":"201506","desc":""},"relativePath":"201506/20150506 Linux FAQs with Answers--How to install Shrew Soft IPsec VPN client on Linux.md","filePath":"[post].md"}'),u={name:"201506/20150506 Linux FAQs with Answers--How to install Shrew Soft IPsec VPN client on Linux.md"};function f(w,e,x,h,P,c){const i=r("Link");return a(),d("div",null,[e[16]||(e[16]=n("h1",{id:"linux有問必答-linux上如何安裝shrew-soft-ipsec-vpn",tabindex:"-1"},[t("Linux有問必答：Linux上如何安裝Shrew Soft IPsec VPN "),n("a",{class:"header-anchor",href:"#linux有問必答-linux上如何安裝shrew-soft-ipsec-vpn","aria-label":"Permalink to “Linux有問必答：Linux上如何安裝Shrew Soft IPsec VPN”"},"​")],-1)),e[17]||(e[17]=n("blockquote",null,[n("p",null,[n("strong",null,"問題"),t("：我需要連接到一個IPSec VPN網關，鑑於此，我嘗試使用Shrew Soft VPN客户端，它是一個免費版本。我怎樣才能安裝Shrew Soft VPN客户端到[某個Linux發行版]?")])],-1)),e[18]||(e[18]=n("p",null,"市面上有許多商業VPN網關，同時附帶有他們自己的專有VPN客户端軟件。雖然也有許多開源的VPN服務器/客户端備選方案，但它們通常缺乏複雜的IPsec支持，比如互聯網密鑰交換（IKE），這是一個標準的IPsec協議，用於加固VPN密鑰交換和驗證安全。Shrew Soft VPN是一個免費的IPsec VPN客户端，它支持多種驗證方法、密鑰交換、加密以及防火牆穿透選項。",-1)),e[19]||(e[19]=n("p",null,"下面介紹如何安裝Shrew Soft VPN客户端到Linux平台。",-1)),n("p",null,[e[1]||(e[1]=t("首先，從",-1)),s(i,{href:"https://www.shrew.net/download/ike"},{default:o(()=>[...e[0]||(e[0]=[t("官方站點",-1)])]),_:1}),e[2]||(e[2]=t("下載它的源代碼。",-1))]),e[20]||(e[20]=p(`<h3 id="安裝shrew-vpn客户端到debian-ubuntu或者linux-mint" tabindex="-1">安裝Shrew VPN客户端到Debian, Ubuntu或者Linux Mint <a class="header-anchor" href="#安裝shrew-vpn客户端到debian-ubuntu或者linux-mint" aria-label="Permalink to “安裝Shrew VPN客户端到Debian, Ubuntu或者Linux Mint”">​</a></h3><p>Shrew Soft VPN客户端圖形界面要求使用Qt 4.x。所以，作為依賴，你需要安裝其開發文件。</p><pre><code>$ sudo apt-get install cmake libqt4-core libqt4-dev libqt4-gui libedit-dev libssl-dev checkinstall flex bison
$ wget https://www.shrew.net/download/ike/ike-2.2.1-release.tbz2
$ tar xvfvj ike-2.2.1-release.tbz2
$ cd ike
$ cmake -DCMAKE_INSTALL_PREFIX=/usr -DQTGUI=YES -DETCDIR=/etc -DNATT=YES .
$ make
$ sudo make install
$ cd /etc/
$ sudo mv iked.conf.sample iked.conf 
</code></pre><h3 id="安裝shrew-vpn客户端到centos-fedora或者rhel" tabindex="-1">安裝Shrew VPN客户端到CentOS, Fedora或者RHEL <a class="header-anchor" href="#安裝shrew-vpn客户端到centos-fedora或者rhel" aria-label="Permalink to “安裝Shrew VPN客户端到CentOS, Fedora或者RHEL”">​</a></h3><p>與基於Debian的系統類似，在編譯前你需要安裝一堆依賴包，包括Qt4。</p><pre><code>$ sudo yum install qt-devel cmake gcc-c++ openssl-devel libedit-devel flex bison
$ wget https://www.shrew.net/download/ike/ike-2.2.1-release.tbz2
$ tar xvfvj ike-2.2.1-release.tbz2
$ cd ike
$ cmake -DCMAKE_INSTALL_PREFIX=/usr -DQTGUI=YES -DETCDIR=/etc -DNATT=YES .
$ make
$ sudo make install
$ cd /etc/
$ sudo mv iked.conf.sample iked.conf 
</code></pre><p>在基於Red Hat的系統中，最後一步需要用文本編輯器打開/etc/ld.so.conf文件，並添加以下行。</p><pre><code>$ sudo vi /etc/ld.so.conf
</code></pre><hr><pre><code>include /usr/lib/
</code></pre><p>重新加載運行時綁定的共享庫文件，以容納新安裝的共享庫：</p><pre><code>$ sudo ldconfig 
</code></pre><h3 id="啓動shrew-vpn客户端" tabindex="-1">啓動Shrew VPN客户端 <a class="header-anchor" href="#啓動shrew-vpn客户端" aria-label="Permalink to “啓動Shrew VPN客户端”">​</a></h3><p>首先，啓動IKE守護進程（iked）。該守護進作為VPN客户端程通過IKE協議與遠程主機經由IPSec通信。</p><pre><code>$ sudo iked 
</code></pre><p><img src="https://farm9.staticflickr.com/8685/17175688940_59c2db64c9_b.jpg" alt=""></p><p>現在，啓動qikea，它是一個IPsec VPN客户端前端。該GUI應用允許你管理遠程站點配置並初始化VPN連接。</p><p><img src="https://farm8.staticflickr.com/7750/16742992713_eed7f97939_b.jpg" alt=""></p><p>要創建一個新的VPN配置，點擊“添加”按鈕，然後填入VPN站點配置。創建配置後，你可以通過點擊配置來初始化VPN連接。</p><p><img src="https://farm8.staticflickr.com/7725/17337297056_3d38dc2180_b.jpg" alt=""></p><h3 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to “故障排除”">​</a></h3><ol><li><p>我在運行iked時碰到了如下錯誤。</p><p>iked: error while loading shared libraries: libss_ike.so.2.2.1: cannot open shared object file: No such file or directory</p></li></ol><p>要解決該問題，你需要更新動態鏈接器來容納libss_ike庫。對於此，請添加庫文件的位置路徑到/etc/ld.so.conf文件中，然後運行ldconfig命令。</p><pre><code>$ sudo ldconfig
</code></pre><p>驗證libss_ike是否添加到了庫路徑：</p><pre><code>$ ldconfig -p | grep ike 
</code></pre><hr><pre><code>libss_ike.so.2.2.1 (libc6,x86-64) =&gt; /lib/libss_ike.so.2.2.1
libss_ike.so (libc6,x86-64) =&gt; /lib/libss_ike.so
</code></pre><hr>`,29)),n("p",null,[e[4]||(e[4]=t("via: ",-1)),s(i,{href:"http://ask.xmodulo.com/install-shrew-soft-ipsec-vpn-client-linux.html"},{default:o(()=>[...e[3]||(e[3]=[t("http://ask.xmodulo.com/install-shrew-soft-ipsec-vpn-client-linux.html",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=t("作者：",-1)),s(i,{href:"http://ask.xmodulo.com/author/nanni"},{default:o(()=>[...e[5]||(e[5]=[t("Dan Nanni",-1)])]),_:1}),e[9]||(e[9]=t(" 譯者：",-1)),s(i,{href:"https://github.com/GOLinux"},{default:o(()=>[...e[6]||(e[6]=[t("GOLinux",-1)])]),_:1}),e[10]||(e[10]=t(" 校對：",-1)),s(i,{href:"https://github.com/wxy"},{default:o(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=t("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原創翻譯，",-1)),s(i,{href:"https://linux.cn/"},{default:o(()=>[...e[12]||(e[12]=[t("Linux中國",-1)])]),_:1}),e[15]||(e[15]=t(" 榮譽推出",-1))])])}const k=l(u,[["render",f]]);export{S as __pageData,k as default};
